def _timed_completion(client, *, label="", **kwargs):
    """Thin wrapper around client.chat.completions.create that logs timing."""
    t0 = _time.perf_counter()
    try:
        resp = client.chat.completions.create(**kwargs)
        elapsed = _time.perf_counter() - t0
        tokens = getattr(resp.usage, 'total_tokens', 0) if resp.usage else 0
        print(f"   [AGENT-TIMING] {label}: {elapsed:.1f}s | {tokens} tok | model={kwargs.get('model','?')}")
        return resp
    except Exception as e:
        elapsed = _time.perf_counter() - t0
        print(f"   [AGENT-TIMING] {label}: FAILED after {elapsed:.1f}s | {type(e).__name__}: {e}")
        raise


def _soft_clamp_index(raw_index, lo, hi):
    """Soft-compress a raw index into [lo, hi], centered on 1.0 (GP parity).

    Pure tanh compression — no parity pull, no noise injection.  The organic
    signal goes in and a compressed-but-directionally-preserved signal comes
    out.  Items above 1.0 stay above; items below stay below.  Extreme
    values are smoothly squeezed toward the bounds without hard clipping.
    """
    center = 1.0
    half_hi = hi - center
    half_lo = center - lo

    if half_hi <= 0 and half_lo <= 0:
        return center

    deviation = raw_index - center

    if deviation >= 0:
        scale = max(half_hi * 2.0, 0.01)
        return center + half_hi * math.tanh(deviation / scale)
    else:
        scale = max(half_lo * 2.0, 0.01)
        return center - half_lo * math.tanh(abs(deviation) / scale)


def soft_bp_ceiling(raw_bp, ceiling=85.0):
    """Smooth ceiling that compresses values approaching the cap.

    Uses a hyperbolic curve (t / (1+t)) that has slope exactly 1.0 at the
    knee point, guaranteeing monotonic compression — output is always <= input.

    Default ceiling is 40% — no single brand should realistically have 70%+
    penetration in any audience. Even mass-market brands like Amazon/Walmart
    rarely exceed 35-40% Brand Penetration in real consumer panels.
    """
    knee = ceiling * 0.80
    if raw_bp <= knee:
        return raw_bp
    overshoot = raw_bp - knee
    headroom = ceiling - knee
    t = overshoot / headroom
    compressed = headroom * t / (1.0 + t)
    return round(knee + compressed, 4)

