def _extract_core_brand(project_name, brands=None):
    """Extract the core brand name from a profile title and its search terms.
    
    Examples:
      project_name="YouTube - Most Viewed", brands=["youtube.com","my youtube"] -> "YOUTUBE"
      project_name="Mr Beast", brands=["mr beast youtube","youtube mr beast"] -> "MR BEAST"
      project_name="Netflix", brands=["netflix.com"] -> "NETFLIX"
      project_name="Taylor Swift", brands=["taylor swift"] -> "TAYLOR SWIFT"
    """
    import re, urllib.parse
    
    # Clean the project name: strip suffixes like "- Most Viewed", "- General", "(2025)", dates
    clean = str(project_name or '').strip()
    clean = re.sub(r'\s*[-–—]\s*(Most Viewed|General|Overall|Listeners?|Watchers?|Players?|Fans?|Purchasers?).*$', '', clean, flags=re.IGNORECASE)
    clean = re.sub(r'\s*\(\d{4}\)$', '', clean)
    clean = re.sub(r'\s*\d{4}$', '', clean)
    clean = re.sub(r'[-._/\\|~#$%&*+=@]+', ' ', clean)
    clean = re.sub(r'\s+', ' ', clean).strip().upper()
    
    candidates = [clean] if clean else []
    
    if brands:
        # Extract domain-based brand names from URLs
        for b in brands:
            b_str = str(b).strip()
            # Pull domain from URLs: youtube.com/mrbeast -> youtube
            domain_match = re.match(r'^(?:https?://)?(?:www\.)?([a-zA-Z0-9]+)\.', b_str)
            if domain_match:
                domain_brand = domain_match.group(1).upper()
                if domain_brand not in ('COM', 'ORG', 'NET', 'IO', 'CO', 'WWW'):
                    if domain_brand not in candidates:
                        candidates.append(domain_brand)
            # Also normalize the full search term
            norm = _normalize_brand_for_lookup(b_str)
            if norm and norm not in candidates:
                candidates.append(norm)
    
    if not candidates:
        return [_normalize_brand_for_lookup(project_name)]
    
    # If project name is multi-word (like "Mr Beast"), it's likely the real brand
    # If search terms all contain a common word that matches project name, use that
    if clean and len(clean.split()) >= 2:
        candidates.insert(0, clean)
    
    # Deduplicate while preserving order
    seen = set()
    unique = []
    for c in candidates:
        if c and c not in seen:
            seen.add(c)
            unique.append(c)
    return unique


def get_genpop_penetration_for_brand(brand_name, brand_category=None, brands=None):
    """Look up a brand's penetration in the Gen Pop CSV.
    
    Intelligently extracts the core brand from the profile name and search terms.
    E.g. project_name="YouTube - Most Viewed" with brands=["youtube.com"] finds YOUTUBE.
    
    Returns (penetration_pct, category_found_in) or (None, None) if not found.
    """
    gp = _load_genpop_csv()
    if gp is None:
        return None, None
    
    candidate_names = _extract_core_brand(brand_name, brands)
    if not candidate_names:
        return None, None
    
    col_name = gp.columns[0]
    val_name = gp.columns[1]
    bp_name = gp.columns[2]
    
    gp_upper = gp.copy()
    gp_upper['_col'] = gp_upper[col_name].astype(str).str.strip().str.upper()
    gp_upper['_val'] = gp_upper[val_name].astype(str).str.strip().str.upper()
    
    search_cats = []
    if brand_category:
        bc_upper = brand_category.strip().upper()
        if bc_upper.startswith('SERIES') or bc_upper.startswith('MOVIE'):
            search_cats = ['STREAMING/PLATFORM', 'FRANCHISE', 'MEDIA']
        elif bc_upper.startswith('GAMES'):
            search_cats = ['GAMES']
        else:
            search_cats = BRAND_CATEGORY_TO_GENPOP_CATS.get(bc_upper, [bc_upper])
    
    all_cats = gp_upper['_col'].unique()
    skip = {'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN',
            'AGE', 'EDUCATION', 'ETHNICITY', 'GENDER', 'INCOME', 'OCCUPATION',
            'LOCATION', 'PARENTAL_STATUS', 'RELATIONSHIP', 'SEXUAL_ORIENTATION',
            'BRAND CATEGORY', 'INTEREST'}
    
    # Pass 1: Try each candidate name in priority category order, then all categories
    for try_name in candidate_names:
        if not try_name:
            continue
        # Try priority categories first
        for cat in search_cats:
            mask = (gp_upper['_col'] == cat) & (gp_upper['_val'] == try_name)
            if mask.any():
                return float(gp_upper.loc[mask].iloc[0][bp_name]), cat
        # Then try all categories
        for cat in all_cats:
            if cat in skip:
                continue
            mask = (gp_upper['_col'] == cat) & (gp_upper['_val'] == try_name)
            if mask.any():
                return float(gp_upper.loc[mask].iloc[0][bp_name]), cat
    
    # Pass 2: Substring/contains match — check if any Gen Pop value contains a candidate
    # (only for candidates with 4+ chars to avoid false positives like "AT" or "FOX")
    gp_vals = gp_upper[~gp_upper['_col'].isin(skip)]
    for try_name in candidate_names:
        if not try_name or len(try_name) < 4:
            continue
        # Check if a Gen Pop value exactly starts with the candidate (e.g. "YOUTUBE" matches "YOUTUBE")
        contains_mask = gp_vals['_val'].str.startswith(try_name + ' ') | (gp_vals['_val'] == try_name)
        if contains_mask.any():
            # If in priority categories, prefer that
            for cat in search_cats:
                cat_match = contains_mask & (gp_vals['_col'] == cat)
                if cat_match.any():
                    return float(gp_vals.loc[cat_match].iloc[0][bp_name]), cat
            # Otherwise take first match
            row = gp_vals.loc[contains_mask].iloc[0]
            return float(row[bp_name]), row['_col']
    
    # Pass 3: Check if any Gen Pop value is contained in the PROFILE NAME only
    # (not search terms, to avoid "mr beast youtube" matching YOUTUBE)
    # e.g. profile "YouTube Most Viewed" contains Gen Pop value "YOUTUBE"
    profile_norm = _normalize_brand_for_lookup(brand_name)
    if profile_norm and len(profile_norm) >= 6:
        for cat in (search_cats + [c for c in all_cats if c not in skip and c not in search_cats]):
            cat_rows = gp_vals[gp_vals['_col'] == cat]
            for idx, row in cat_rows.iterrows():
                gp_val = row['_val']
                if len(gp_val) >= 4 and gp_val in profile_norm:
                    return float(row[bp_name]), cat
    
    return None, None

def estimate_sample_size_for_unknown_brand(brand_category, actual_universe_size=None):
    """Estimate a reasonable sample size for a brand not found in Gen Pop.
    
    Uses digital panel tier estimates based on BRAND CATEGORY.
    If actual_universe_size is available, uses it to position within the tier range.
    """
    GENPOP_CAP = 10_000_000
    bc_upper = (brand_category or '').strip().upper()
    if bc_upper.startswith('SERIES') or bc_upper.startswith('MOVIE'):
        bc_upper = 'STREAMING/PLATFORM'
    elif bc_upper.startswith('GAMES'):
        bc_upper = 'GAMES'
    
    tier = DIGITAL_PANEL_TIER_ESTIMATES.get(bc_upper, (0.01, 0.08))
    lo, hi = tier
    
    if actual_universe_size and actual_universe_size > 0:
        ratio = min(actual_universe_size / GENPOP_CAP, 1.0)
        pct = lo + (hi - lo) * ratio
    else:
        pct = (lo + hi) / 2
    
    sample_size = round(pct * GENPOP_CAP)
    sample_size = max(sample_size, 10_000)
    sample_size = min(sample_size, GENPOP_CAP)
    sample_size = (sample_size // 10) * 10
    return sample_size

def _get_profile_genpop_penetration(df, gp_lookup):
    """Determine the profile's Gen Pop Brand Penetration from the BRAND INPUT row.

    Looks up the input brand in the Gen Pop lookup to find its BP.
    Falls back to estimating from the sample size vs 10M Gen Pop panel.
    """
    GENPOP_PANEL = 10_000_000

    brand_rows = df[df['Column'].str.upper() == 'BRAND INPUT']
    if not brand_rows.empty:
        brand_val = str(brand_rows.iloc[0].get('Value', '')).strip().upper()
        for (cat, val), entry in gp_lookup.items():
            if val == brand_val or brand_val in val or val in brand_val:
                return entry['bp']

    sample_rows = df[df['Column'].str.upper() == 'SAMPLE SIZE']
    if not sample_rows.empty:
        try:
            raw = str(sample_rows.iloc[0].get('Original Raw Numbers', '0')).replace(',', '')
            ss = int(float(raw))
            return min(99.0, (ss / GENPOP_PANEL) * 100.0)
        except (ValueError, TypeError):
            pass

    return 50.0


def anchor_to_genpop(df, sample_size):
    """Anchor all profile values to the Gen Pop CSV baseline using index-and-anchor.

    Produces ORGANIC variation: some items over-index, some under-index, some
    are near parity — just like real consumer panel data.  No audience buys
    every brand more than the general population.

    Key design principles:
    - Tight bounds centered near Gen Pop (typical index range ~70-180)
    - Per-item deterministic noise creates organic scatter (some under, some over)
    - Absolute BP ceiling of 40% — no single brand realistically captures 70%+
    - Niche profiles get slightly wider bounds (up to ~2.2x) but never absurd
    """
    gp = _load_genpop_csv()
    if gp is None:
        print("⚠️ Gen Pop CSV not available — skipping anchor_to_genpop")
        return df

    df = df.copy()

    DEMO_CATS = {
        'AGE', 'GENDER', 'ETHNICITY', 'INCOME', 'EDUCATION',
        'RELATIONSHIP', 'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'OCCUPATION',
    }
    SKIP_CATS = {
        'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN',
        'CASUAL FAN', 'BRAND CATEGORY',
    }
    SKIP_CATS = SKIP_CATS | DEMO_CATS

    gp_col = gp.columns[0]   # Column
    gp_val = gp.columns[1]   # Value
    gp_bp  = gp.columns[2]   # Brand Penetration (Row)
    gp_cs  = gp.columns[3]   # Category Share

    gp_lookup = {}
    for _, row in gp.iterrows():
        cat = str(row[gp_col]).strip().upper()
        val = str(row[gp_val]).strip().upper()
        if cat in SKIP_CATS:
            continue
        try:
            bp = float(row[gp_bp])
            cs = float(row[gp_cs])
        except (ValueError, TypeError):
            continue
        gp_lookup[(cat, val)] = {'bp': bp, 'cs': cs}

    pct_col = 'Category Share' if 'Category Share' in df.columns else 'Percentage'
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in df.columns else None
    read_col = bp_col or pct_col

    sample_size = max(int(float(sample_size)), 1)

    profile_bp_pct = _get_profile_genpop_penetration(df, gp_lookup)
    niche_factor = (1.0 - profile_bp_pct / 100.0) ** 2  # 0 for Gen Pop, ~1 for niche

    BEHAV_HI = min(2.20, 1.0 + 0.50 + 1.20 * niche_factor)
    BEHAV_LO = max(0.40, 1.0 - 0.30 - 0.30 * niche_factor)
    DEMO_HI  = max(1.10, 1.0 + 0.8 * niche_factor)
    DEMO_LO  = min(0.92, 1.0 - 0.5 * niche_factor)

    # Base BP ceiling for niche items. For mass-market items (high GP BP),
    # the ceiling is raised so they can still reach index ~100-120.
    # Formula: max(40%, gp_bp * 1.15) — allows up to ~115% of Gen Pop BP.
    BP_CEILING_BASE = 40.0

    print(f"   Profile Gen Pop penetration: {profile_bp_pct:.1f}% → "
          f"behav bounds [{BEHAV_LO:.2f}, {BEHAV_HI:.2f}], "
          f"demo bounds [{DEMO_LO:.2f}, {DEMO_HI:.2f}], "
          f"BP ceiling base: {BP_CEILING_BASE}%")

    # Capture original profile CS ranking per category before anchoring.
    # Used later to enforce rank-order preservation.
    _orig_cs_by_cat = {}
    for idx, row in df.iterrows():
        cat = str(row.get('Column', '')).strip().upper()
        if cat in SKIP_CATS:
            continue
        val = str(row.get('Value', '')).strip().upper()
        try:
            orig_cs = float(row.get(pct_col, 0))
        except (ValueError, TypeError):
            orig_cs = 0
        _orig_cs_by_cat.setdefault(cat, []).append((val, orig_cs, idx))

    changes = 0
    for idx, row in df.iterrows():
        cat = str(row.get('Column', '')).strip().upper()
        val = str(row.get('Value', '')).strip().upper()

        if cat in SKIP_CATS:
            continue

        is_demo = cat in DEMO_CATS
        base_lo, base_hi = (DEMO_LO, DEMO_HI) if is_demo else (BEHAV_LO, BEHAV_HI)

        gp_entry = gp_lookup.get((cat, val))
        if gp_entry is None:
            continue

        gp_bp_val = gp_entry['bp']

        if gp_bp_val <= 0:
            continue

        try:
            profile_bp_val = float(row.get(read_col, 0))
        except (ValueError, TypeError):
            profile_bp_val = 0

        if profile_bp_val <= 0:
            continue

        # Per-item adaptive ceiling: niche items cap at 40%, mass-market items
        # (with high GP BP) can reach up to ~115% of their Gen Pop BP so they
        # don't get artificially forced below index 100.
        item_ceiling = max(BP_CEILING_BASE, gp_bp_val * 1.15)

        # Raw ratio = profile BP / Gen Pop BP — the standard consumer index.
        # This preserves the organic signal from the underlying data.
        # Bayesian shrinkage blends toward 1.0 when raw count is small.
        try:
            raw_count = int(float(str(row.get('Original Raw Numbers', '0')).replace(',', '')))
        except (ValueError, TypeError):
            raw_count = 0
        confidence = min(1.0, raw_count / 500.0)
        raw_ratio = profile_bp_val / gp_bp_val
        raw_index = confidence * raw_ratio + (1.0 - confidence) * 1.0

        lo = base_lo
        hi = base_hi

        # Per-item adaptive floor: preserve genuine under-indexing signal
        if not is_demo and raw_ratio < base_lo:
            lo = max(0.20, raw_ratio * 0.8)

        # Popularity dampening: mass-market items (high GP BP) have a narrower
        # range centered on 1.0 (GP parity). Niche items keep the wide range.
        # Gentler formula prevents over-compression of ubiquitous brands
        # (YouTube, Google, Amazon) that should stay near Gen Pop for most audiences.
        if not is_demo:
            popularity_scale = max(0.50, 1.0 - gp_bp_val / 200.0)
            hi = 1.0 + (hi - 1.0) * popularity_scale
            lo = 1.0 - (1.0 - lo) * popularity_scale

        # Enforce per-item ceiling: prevents unrealistic BP inflation
        if not is_demo and gp_bp_val > 0:
            max_index_from_ceiling = item_ceiling / gp_bp_val
            hi = min(hi, max_index_from_ceiling)
            hi = max(hi, 1.01)

        clamped_index = _soft_clamp_index(raw_index, lo, hi)

        new_bp = gp_bp_val * clamped_index
        new_bp = soft_bp_ceiling(new_bp, ceiling=item_ceiling)
        new_bp = round(new_bp, 4)

        new_raw = max(1, int(round(new_bp / 100.0 * sample_size)))
        new_genpop = int(round((new_raw / 10_000_000) * 329_900_000))

        if bp_col and bp_col in df.columns:
            df.at[idx, bp_col] = new_bp
        df.at[idx, read_col] = new_bp
        df.at[idx, 'Original Raw Numbers'] = str(new_raw)
        if 'US Gen Pop Projection' in df.columns:
            df.at[idx, 'US Gen Pop Projection'] = str(new_genpop)

        changes += 1

    # --- Pass 2: Cap items with NO Gen Pop match ---
    UNMATCHED_CEILING = 20.0
    unmatched_fixes = 0
    for idx, row in df.iterrows():
        cat = str(row.get('Column', '')).strip().upper()
        val = str(row.get('Value', '')).strip().upper()
        if cat in SKIP_CATS:
            continue
        gp_entry = gp_lookup.get((cat, val))
        if gp_entry is not None:
            continue
        try:
            cur_bp = float(row.get(read_col, 0))
        except (ValueError, TypeError):
            continue
        if cur_bp <= UNMATCHED_CEILING or cur_bp <= 0:
            continue
        new_bp = round(soft_bp_ceiling(cur_bp, ceiling=UNMATCHED_CEILING), 4)
        new_raw = max(1, int(round(new_bp / 100.0 * sample_size)))
        new_genpop = int(round((new_raw / 10_000_000) * 329_900_000))
        if bp_col and bp_col in df.columns:
            df.at[idx, bp_col] = new_bp
        df.at[idx, read_col] = new_bp
        df.at[idx, 'Original Raw Numbers'] = str(new_raw)
        if 'US Gen Pop Projection' in df.columns:
            df.at[idx, 'US Gen Pop Projection'] = str(new_genpop)
        unmatched_fixes += 1
    if unmatched_fixes:
        print(f"   ⚠️  Capped {unmatched_fixes} unmatched items (no Gen Pop benchmark) "
              f"at ~{UNMATCHED_CEILING}%")

    # --- Rank-order preservation ---
    # After anchoring, the BP values may be reordered relative to the
    # raw profile's CS ranking because the formula new_bp = gp_bp * index
    # is dominated by gp_bp when indices compress toward 1.0.
    # Restore the raw profile's CS rank ordering: if the raw profile
    # ranked item A above item B (by CS), ensure A's anchored BP >= B's.
    rank_swaps = 0
    for cat, orig_items in _orig_cs_by_cat.items():
        if cat in DEMO_CATS:
            continue
        # Sort by original CS descending — this is the profile's rank
        profile_order = sorted(orig_items, key=lambda x: -x[1])
        # Get current anchored BPs for these items
        anchored_bps = []
        for val, orig_cs, ridx in profile_order:
            try:
                cur_bp = float(df.at[ridx, read_col])
            except (ValueError, TypeError):
                cur_bp = 0
            anchored_bps.append(cur_bp)
        bp_slots = sorted(anchored_bps, reverse=True)
        for i, (val, orig_cs, ridx) in enumerate(profile_order):
            if i < len(bp_slots):
                old_bp = anchored_bps[i]
                new_bp_val = bp_slots[i]
                if abs(old_bp - new_bp_val) > 0.001:
                    df.at[ridx, read_col] = round(new_bp_val, 4)
                    if bp_col and bp_col in df.columns:
                        df.at[ridx, bp_col] = round(new_bp_val, 4)
                    new_raw = max(1, int(round(new_bp_val / 100.0 * sample_size)))
                    df.at[ridx, 'Original Raw Numbers'] = str(new_raw)
                    if 'US Gen Pop Projection' in df.columns:
                        df.at[ridx, 'US Gen Pop Projection'] = str(
                            int(round((new_raw / 10_000_000) * 329_900_000)))
                    rank_swaps += 1
    if rank_swaps:
        print(f"   🔄 Rank preservation: {rank_swaps} items reordered to "
              f"match raw profile signal")

    # --- Cross-category harmonization ---
    # Same brand in multiple categories (e.g. NBC in BROADCAST/CABLE + MEDIA)
    # gets averaged to a single consistent BP value.
    DEMO_CATS_SET = SKIP_CATS | {'LOCATION'}
    val_occ = {}
    for idx, row in df.iterrows():
        cat = str(row.get('Column', '')).strip().upper()
        if cat in DEMO_CATS_SET:
            continue
        val = str(row.get('Value', '')).strip().upper()
        if not val:
            continue
        try:
            cur_bp = float(row.get(read_col, 0))
        except (ValueError, TypeError):
            continue
        val_occ.setdefault(val, []).append((idx, cur_bp))
    harm_count = 0
    for val, entries in val_occ.items():
        if len(entries) < 2:
            continue
        bps = [bp for _, bp in entries]
        if max(bps) - min(bps) < 0.01:
            continue
        avg_bp = round(sum(bps) / len(bps), 4)
        for ridx, old_bp in entries:
            if abs(old_bp - avg_bp) < 0.01:
                continue
            df.at[ridx, read_col] = avg_bp
            if bp_col and bp_col in df.columns:
                df.at[ridx, bp_col] = avg_bp
            new_raw = max(1, int(round(avg_bp / 100.0 * sample_size)))
            df.at[ridx, 'Original Raw Numbers'] = str(new_raw)
            if 'US Gen Pop Projection' in df.columns:
                df.at[ridx, 'US Gen Pop Projection'] = str(
                    int(round((new_raw / 10_000_000) * 329_900_000)))
            harm_count += 1
    if harm_count:
        print(f"   🔗 Cross-category harmonization: {harm_count} values aligned")

    for cat in df['Column'].str.upper().unique():
        if cat in SKIP_CATS:
            continue
        cat_mask = df['Column'].str.upper() == cat
        if not cat_mask.any():
            continue

        raw_col_name = 'Original Raw Numbers'
        if raw_col_name not in df.columns:
            continue

        total_raw = 0
        for cidx in df[cat_mask].index:
            try:
                total_raw += int(float(str(df.at[cidx, raw_col_name]).replace(',', '')))
            except (ValueError, TypeError):
                pass

        if total_raw <= 0:
            continue

        for cidx in df[cat_mask].index:
            try:
                raw = int(float(str(df.at[cidx, raw_col_name]).replace(',', '')))
                new_cs = round((raw / total_raw) * 100.0, 4)
                df.at[cidx, pct_col] = f"{new_cs:.4f}" if isinstance(df.at[cidx, pct_col], str) else new_cs
            except (ValueError, TypeError):
                pass

    print(f"✅ anchor_to_genpop: anchored {changes} rows to Gen Pop baseline")
    return df


