            new_total = sum(
                float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                for ix in all_idx
            )
            if new_total > 0:
                for ix in all_idx:
                    bp = float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                    df.at[ix, cs_col] = f"{bp / new_total * 100.0:.4f}%"

