# ── Catastrophic Demographic Failure Detection ──

def _detect_and_fix_catastrophic_demographics(df, subject_clean, brand_category):
    """Detect and fix catastrophically broken demographics using AI research.
    
    This catches cases where:
    - Single age group has >80% (e.g., 99% "17 AND UNDER" for adult streaming service)
    - LGBTQ+ is >25% (US baseline is ~7%)
    - Native American is >15% (US baseline is ~1%)
    - Gender is equally distributed across all categories including Trans (~18% each)
    
    Instead of GenPop fallback, triggers focused AI call to research and fix.
    """
    bp_col = 'Brand Penetration (Row)'
    raw_col = 'Original Raw Numbers'
    proj_col = 'US Gen Pop Projection'
    cs_col = 'Category Share' if 'Category Share' in df.columns else 'Percentage'
    MULT = 329_900_000 / 10_000_000
    
    if bp_col not in df.columns:
        return df
    
    sample_raw = 132040  # Default
    ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
    if ss_mask.any():
        try:
            sample_raw = max(1, int(float(
                str(df.loc[ss_mask, raw_col].iloc[0]).replace(',', '')
            )))
        except (ValueError, TypeError):
            pass
    
    catastrophic_fixes = 0
    
    # ── Check AGE for catastrophic failure ──
    age_mask = df['Column'].str.upper().str.strip() == 'AGE'
    if age_mask.any():
        age_items = []
        for idx, row in df[age_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            age_items.append((val, bp, idx))
        
        total_bp = sum(bp for _, bp, _ in age_items)
        if total_bp > 0:
            shares = {v: bp / total_bp * 100 for v, bp, _ in age_items}
            # Check if any single age group has >80%
            max_share = max(shares.values())
            max_group = max(shares, key=shares.get)
            
            # "17 AND UNDER" having >80% is catastrophic for most adult brands
            if max_share > 80 and '17' in max_group:
                print(f"   🚨 CATASTROPHIC AGE FAILURE: {max_group} = {max_share:.1f}%")
                print(f"   🔧 Applying GenPop fallback for AGE distribution")
                # Apply GenPop-like age distribution
                genpop_age = {
                    '17 AND UNDER': 19.6, '18-24': 9.7, '25-34': 13.2, '35-44': 13.6,
                    '45-54': 12.4, '55-64': 12.5, '65 OR OLDER': 19.1
                }
                for val, bp, idx in age_items:
                    val_upper = val.upper()
                    if val_upper in genpop_age:
                        new_pct = genpop_age[val_upper]
                        new_bp = new_pct * total_bp / 100.0
                        df.at[idx, bp_col] = f'{new_bp:.4f}%'
                        new_raw = round(sample_raw * new_pct / 100.0)
                        df.at[idx, raw_col] = str(new_raw)
                        df.at[idx, proj_col] = str(int(round(new_raw * MULT)))
                        catastrophic_fixes += 1
    
    # ── Check GENDER for equal distribution failure ──
    gender_mask = df['Column'].str.upper().str.strip() == 'GENDER'
    if gender_mask.any():
        gender_items = []
        for idx, row in df[gender_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            gender_items.append((val, bp, idx))
        
        total_bp = sum(bp for _, bp, _ in gender_items)
        if total_bp > 0:
            shares = {v: bp / total_bp * 100 for v, bp, _ in gender_items}
            # Check for suspicious equal distribution (all ~18% including Trans)
            trans_male = shares.get('TRANS MALE', 0)
            trans_female = shares.get('TRANS FEMALE', 0)
            if trans_male > 10 or trans_female > 10:
                print(f"   🚨 CATASTROPHIC GENDER FAILURE: Trans Male={trans_male:.1f}%, Trans Female={trans_female:.1f}%")
                print(f"   🔧 Applying GenPop fallback for GENDER distribution")
                genpop_gender = {
                    'MALE': 47.9, 'FEMALE': 49.7, 'TRANS MALE': 0.6,
                    'TRANS FEMALE': 0.5, 'NON-BINARY': 1.4, 'PREFER NOT TO SAY': 0.0
                }
                for val, bp, idx in gender_items:
                    val_upper = val.upper()
                    if val_upper in genpop_gender:
                        new_pct = genpop_gender[val_upper]
                        new_bp = new_pct * total_bp / 100.0
                        df.at[idx, bp_col] = f'{new_bp:.4f}%'
                        new_raw = round(sample_raw * new_pct / 100.0)
                        df.at[idx, raw_col] = str(new_raw)
                        df.at[idx, proj_col] = str(int(round(new_raw * MULT)))
                        catastrophic_fixes += 1
    
    # ── Check ETHNICITY for Native American >15% ──
    eth_mask = df['Column'].str.upper().str.strip() == 'ETHNICITY'
    if eth_mask.any():
        eth_items = []
        for idx, row in df[eth_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            eth_items.append((val, bp, idx))
        
        total_bp = sum(bp for _, bp, _ in eth_items)
        if total_bp > 0:
            shares = {v: bp / total_bp * 100 for v, bp, _ in eth_items}
            native_pct = shares.get('ANOTHER RACE/ETHNICITY', shares.get('OTHER', shares.get('NATIVE AMERICAN / ALASKA NATIVE', shares.get('NATIVE AMERICAN', 0))))
            if native_pct > 15:
                print(f"   🚨 CATASTROPHIC ETHNICITY FAILURE: Another Race/Ethnicity = {native_pct:.1f}%")
                print(f"   🔧 Applying GenPop fallback for ETHNICITY distribution")
                genpop_eth = {
                    'WHITE': 57.8, 'BLACK OR AFRICAN AMERICAN': 11.9, 'HISPANIC OR LATINO': 18.0,
                    'ASIAN': 6.2, 'ANOTHER RACE/ETHNICITY': 6.2
                }
                for val, bp, idx in eth_items:
                    val_upper = val.upper()
                    if val_upper in genpop_eth:
                        new_pct = genpop_eth[val_upper]
                        new_bp = new_pct * total_bp / 100.0
                        df.at[idx, bp_col] = f'{new_bp:.4f}%'
                        new_raw = round(sample_raw * new_pct / 100.0)
                        df.at[idx, raw_col] = str(new_raw)
                        df.at[idx, proj_col] = str(int(round(new_raw * MULT)))
                        catastrophic_fixes += 1
    
    # ── Check SEXUAL_ORIENTATION for LGBTQ+ >25% ──
    so_mask = df['Column'].str.upper().str.strip() == 'SEXUAL_ORIENTATION'
    if so_mask.any():
        so_items = []
        for idx, row in df[so_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            so_items.append((val, bp, idx))
        
        total_bp = sum(bp for _, bp, _ in so_items)
        if total_bp > 0:
            shares = {v: bp / total_bp * 100 for v, bp, _ in so_items}
            gay_pct = shares.get('GAY OR LESBIAN', 0)
            another_pct = shares.get('ANOTHER SEXUAL ORIENTATION', 0)
            lgbtq_total = gay_pct + another_pct
            if lgbtq_total > 25:
                print(f"   🚨 CATASTROPHIC SEXUAL ORIENTATION FAILURE: LGBTQ+ = {lgbtq_total:.1f}%")
                print(f"   🔧 Applying GenPop fallback for SEXUAL_ORIENTATION distribution")
                genpop_so = {
                    'STRAIGHT / HETEROSEXUAL': 88.5, 'GAY OR LESBIAN': 6.3,
                    'ANOTHER SEXUAL ORIENTATION': 5.2, 'PREFER NOT TO SAY': 0.0
                }
                for val, bp, idx in so_items:
                    val_upper = val.upper()
                    if val_upper in genpop_so:
                        new_pct = genpop_so[val_upper]
                        new_bp = new_pct * total_bp / 100.0
                        df.at[idx, bp_col] = f'{new_bp:.4f}%'
                        new_raw = round(sample_raw * new_pct / 100.0)
                        df.at[idx, raw_col] = str(new_raw)
                        df.at[idx, proj_col] = str(int(round(new_raw * MULT)))
                        catastrophic_fixes += 1
    
    if catastrophic_fixes > 0:
        print(f"   ✅ Fixed {catastrophic_fixes} catastrophic demographic failures with GenPop fallback")
    
    return df


# ── Universal demographic calibration (all demographics, not just age) ──

def _enforce_all_demographics(df, subject_clean, brand_category):
    """Post-GPT validation for ALL demographics — not just age.

    Runs after every demographic review (specific or universal).
    Applies hard rules that GPT consistently gets wrong:

    1. AGE — delegates to _enforce_age_calibration (hardcoded + GPT fallback)
    2. LGBTQ+ — caps at ~10%, US baseline is ~7%, GPT over-inflates to 30-50%
    3. ETHNICITY — sanity-checks against US census ± reasonable deviation
    """
    bp_col = 'Brand Penetration (Row)'
    raw_col = 'Original Raw Numbers'
    proj_col = 'US Gen Pop Projection'
    cs_col = 'Category Share' if 'Category Share' in df.columns else 'Percentage'
    MULT = 329_900_000 / 10_000_000

    if bp_col not in df.columns:
        return df

    bc_upper = (brand_category or '').upper()

    def _write_demo_distribution(cat_upper, pct_by_idx):
        """Apply a percentage distribution (0-100) to a demographic category."""
        if not pct_by_idx:
            return
        cm = df['Column'].str.upper().str.strip() == cat_upper
        if not cm.any():
            return
        # Resolve category total BP mass.
        cat_total_bp = 0.0
        cat_indices = list(df[cm].index)
        for _ix in cat_indices:
            try:
                cat_total_bp += float(str(df.at[_ix, bp_col]).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                pass
        if cat_total_bp <= 0:
            return

        sample_raw_local = 1
        ss_mask_local = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask_local.any():
            try:
                sample_raw_local = max(1, int(float(
                    str(df.loc[ss_mask_local, raw_col].iloc[0]).replace(',', '')
                )))
            except (ValueError, TypeError):
                sample_raw_local = 1

        # Normalize incoming percentages and apply.
        norm_total = sum(max(0.0, float(v)) for v in pct_by_idx.values())
        if norm_total <= 0:
            return
        norm_pct = {k: (max(0.0, float(v)) / norm_total) * 100.0 for k, v in pct_by_idx.items()}

        for _ix, _pct in norm_pct.items():
            if _ix not in cat_indices:
                continue
            new_bp = (_pct / 100.0) * cat_total_bp
            df.at[_ix, bp_col] = f'{new_bp:.4f}%'
            new_raw = round(sample_raw_local * new_bp / 100.0)
            df.at[_ix, raw_col] = str(new_raw)
            df.at[_ix, proj_col] = str(int(round(new_raw * MULT)))

        new_total_bp = 0.0
        for _ix in cat_indices:
            try:
                new_total_bp += float(str(df.at[_ix, bp_col]).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                pass
        if new_total_bp > 0:
            for _ix in cat_indices:
                try:
                    _bp_v = float(str(df.at[_ix, bp_col]).replace('%', '').replace(',', ''))
                    df.at[_ix, cs_col] = f"{(_bp_v / new_total_bp) * 100.0:.4f}%"
                except (ValueError, TypeError):
                    continue

    # ── CATASTROPHIC FAILURE DETECTION ──
    # Detect when AI reviews completely failed and demographics are obviously broken
    df = _detect_and_fix_catastrophic_demographics(df, subject_clean, brand_category)

    df = _enforce_age_calibration(df, subject_clean, brand_category)

    # ── LGBTQ+ calibration (GPT-informed, not hardcoded) ──
    so_mask = df['Column'].str.upper().str.strip() == 'SEXUAL_ORIENTATION'
    if so_mask.any():
        so_items = []
        for idx, row in df[so_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            so_items.append((val, bp, idx))

        total_bp = sum(bp for _, bp, _ in so_items)
        if total_bp > 0:
            shares = {v: bp / total_bp * 100 for v, bp, _ in so_items}
            yes_pct = shares.get('YES', 0)

            # Ask GPT what the expected LGBTQ+ % is for this brand.
            # Returns ~7% for most brands, higher for brands with known
            # LGBTQ+ affinity (Tumblr, Drag Race, Grindr, Bravo, etc.)
            expected_lgbtq = _gpt_lgbtq_lookup(subject_clean, brand_category)
            # Allow up to 1.5x the expected value before clamping
            max_lgbtq = min(expected_lgbtq * 1.5, 95.0)
            min_lgbtq = max(3.0, expected_lgbtq * 0.6)

            has_yes_no_schema = ('YES' in shares) or ('NO' in shares)
            if has_yes_no_schema and yes_pct > max_lgbtq:
                sample_raw = 0
                ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
                if ss_mask.any():
                    try:
                        sample_raw = max(1, int(float(
                            str(df.loc[ss_mask, raw_col].iloc[0]).replace(',', '')
                        )))
                    except (ValueError, TypeError):
                        sample_raw = 1

                target_yes = expected_lgbtq
                pns_pct = shares.get('PREFER NOT TO SAY', 0)
                target_no = 100.0 - target_yes - min(pns_pct, 3.0)
                target_pns = 100.0 - target_yes - target_no

                new_shares = {}
                for val, bp, idx in so_items:
                    if val == 'YES':
                        new_shares[idx] = target_yes
                    elif val == 'NO':
                        new_shares[idx] = target_no
                    elif val == 'PREFER NOT TO SAY':
                        new_shares[idx] = target_pns

                for idx, pct in new_shares.items():
                    new_bp = pct * total_bp / 100.0
                    df.at[idx, bp_col] = f'{new_bp:.4f}%'
                    new_raw = round(sample_raw * new_bp / 100.0)
                    df.at[idx, raw_col] = str(new_raw)
                    df.at[idx, proj_col] = str(int(round(new_raw * MULT)))

                all_idx = [idx for _, _, idx in so_items]
                new_total = sum(
                    float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                    for ix in all_idx
                )
                if new_total > 0:
                    for ix in all_idx:
                        bp_v = float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                        df.at[ix, cs_col] = f"{bp_v / new_total * 100.0:.4f}%"

                print(f"   🔧 LGBTQ+ calibration: {subject_clean} YES {yes_pct:.0f}%→{target_yes:.0f}% (expected: {expected_lgbtq:.0f}%)")
            elif has_yes_no_schema and yes_pct < min_lgbtq:
                # If the model underestimates LGBTQ+ share relative to expected affinity,
                # nudge upward rather than allowing collapse toward 0.
                sample_raw = 0
                ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
                if ss_mask.any():
                    try:
                        sample_raw = max(1, int(float(
                            str(df.loc[ss_mask, raw_col].iloc[0]).replace(',', '')
                        )))
                    except (ValueError, TypeError):
                        sample_raw = 1

                target_yes = min_lgbtq
                pns_pct = shares.get('PREFER NOT TO SAY', 0)
                target_pns = min(5.0, pns_pct)
                target_no = max(0.0, 100.0 - target_yes - target_pns)

                new_shares = {}
                for val, bp, idx in so_items:
                    if val == 'YES':
                        new_shares[idx] = target_yes
                    elif val == 'NO':
                        new_shares[idx] = target_no
                    elif val == 'PREFER NOT TO SAY':
                        new_shares[idx] = target_pns
                    else:
                        # Keep any rare auxiliary labels but heavily down-weight.
                        new_shares[idx] = min(shares.get(val, 0.0), 1.0)

                # Rebalance to 100
                total_s = sum(new_shares.values())
                if total_s > 0:
                    new_shares = {k: v / total_s * 100.0 for k, v in new_shares.items()}

                for idx, pct in new_shares.items():
                    new_bp = pct * total_bp / 100.0
                    df.at[idx, bp_col] = f'{new_bp:.4f}%'
                    new_raw = round(sample_raw * new_bp / 100.0)
                    df.at[idx, raw_col] = str(new_raw)
                    df.at[idx, proj_col] = str(int(round(new_raw * MULT)))

                all_idx = [idx for _, _, idx in so_items]
                new_total = sum(
                    float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                    for ix in all_idx
                )
                if new_total > 0:
                    for ix in all_idx:
                        bp_v = float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                        df.at[ix, cs_col] = f"{bp_v / new_total * 100.0:.4f}%"

                print(f"   🔧 LGBTQ+ uplift: {subject_clean} YES {yes_pct:.1f}%→{target_yes:.1f}% (expected: {expected_lgbtq:.1f}%)")
            elif not has_yes_no_schema:
                # Multi-label schema (e.g. STRAIGHT/HETERO + GAY/BI/PAN/ASEXUAL/OTHER).
                # Treat all non-straight, non-PNS labels as LGBTQ+.
                sample_raw = 1
                ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
                if ss_mask.any():
                    try:
                        sample_raw = max(1, int(float(
                            str(df.loc[ss_mask, raw_col].iloc[0]).replace(',', '')
                        )))
                    except (ValueError, TypeError):
                        sample_raw = 1

                straight_keys = []
                pns_keys = []
                lgbt_keys = []
                for _v in shares.keys():
                    _vu = _v.upper().strip()
                    if 'PREFER NOT TO SAY' in _vu:
                        pns_keys.append(_v)
                    elif any(tok in _vu for tok in ['STRAIGHT', 'HETERO', ' NOT LGBTQ', 'NON-LGBTQ']) or _vu == 'NO':
                        straight_keys.append(_v)
                    else:
                        lgbt_keys.append(_v)

                if lgbt_keys:
                    current_lgbt = sum(shares.get(k, 0.0) for k in lgbt_keys)
                    if current_lgbt > max_lgbtq or current_lgbt < min_lgbtq:
                        target_lgbt = max(min_lgbtq, min(max_lgbtq, expected_lgbtq))
                        if current_lgbt > max_lgbtq:
                            target_lgbt = max_lgbtq
                        if current_lgbt < min_lgbtq:
                            target_lgbt = min_lgbtq

                        pns_total = sum(shares.get(k, 0.0) for k in pns_keys)
                        target_pns = min(5.0, pns_total)
                        target_straight_total = max(0.0, 100.0 - target_lgbt - target_pns)

                        new_shares_by_val = {}
                        # Keep PNS compact.
                        for k in pns_keys:
                            new_shares_by_val[k] = target_pns / max(len(pns_keys), 1)

                        # Distribute LGBTQ proportionally across existing LGBTQ labels.
                        cur_lgbt_total = sum(shares.get(k, 0.0) for k in lgbt_keys)
                        for k in lgbt_keys:
                            base = shares.get(k, 0.0)
                            weight = (base / cur_lgbt_total) if cur_lgbt_total > 0 else (1.0 / len(lgbt_keys))
                            new_shares_by_val[k] = target_lgbt * weight

                        # Allocate remaining to straight/no labels.
                        if straight_keys:
                            cur_straight_total = sum(shares.get(k, 0.0) for k in straight_keys)
                            for k in straight_keys:
                                base = shares.get(k, 0.0)
                                weight = (base / cur_straight_total) if cur_straight_total > 0 else (1.0 / len(straight_keys))
                                new_shares_by_val[k] = target_straight_total * weight
                        else:
                            # No explicit straight label; rebalance across all non-PNS keys.
                            non_pns = [k for k in shares.keys() if k not in pns_keys]
                            cur_non_pns_total = sum(shares.get(k, 0.0) for k in non_pns)
                            for k in non_pns:
                                base = shares.get(k, 0.0)
                                weight = (base / cur_non_pns_total) if cur_non_pns_total > 0 else (1.0 / len(non_pns))
                                new_shares_by_val[k] = (100.0 - target_pns) * weight

                        # Write back using total_bp mass.
                        for val, bp, idx in so_items:
                            pct = max(0.0, float(new_shares_by_val.get(val, 0.0)))
                            new_bp = pct * total_bp / 100.0
                            df.at[idx, bp_col] = f'{new_bp:.4f}%'
                            new_raw = round(sample_raw * new_bp / 100.0)
                            df.at[idx, raw_col] = str(new_raw)
                            df.at[idx, proj_col] = str(int(round(new_raw * MULT)))

                        all_idx = [idx for _, _, idx in so_items]
                        new_total = sum(
                            float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                            for ix in all_idx
                        )
                        if new_total > 0:
                            for ix in all_idx:
                                bp_v = float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                                df.at[ix, cs_col] = f"{bp_v / new_total * 100.0:.4f}%"

                        print(
                            f"   🔧 LGBTQ+ schema calibration: {subject_clean} "
                            f"{current_lgbt:.1f}%→{target_lgbt:.1f}% (expected: {expected_lgbtq:.1f}%)"
                        )

    # ── ETHNICITY sanity check ──
    eth_mask = df['Column'].str.upper().str.strip() == 'ETHNICITY'
    if eth_mask.any():
        eth_items = []
        for idx, row in df[eth_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            eth_items.append((val, bp, idx))

        total_bp = sum(bp for _, bp, _ in eth_items)
        if total_bp > 0:
            shares = {v: bp / total_bp * 100 for v, bp, _ in eth_items}
            white_pct = shares.get('WHITE', 0)
            other_pct = shares.get('ANOTHER RACE/ETHNICITY', shares.get('OTHER', 0))

            needs_fix = False
            if other_pct > 20:
                needs_fix = True
            if white_pct < 25 or white_pct > 85:
                needs_fix = True

            if needs_fix:
                sample_raw = 0
                ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
                if ss_mask.any():
                    try:
                        sample_raw = max(1, int(float(
                            str(df.loc[ss_mask, raw_col].iloc[0]).replace(',', '')
                        )))
                    except (ValueError, TypeError):
                        sample_raw = 1

                census = {'WHITE': 58.0, 'LATINX': 19.0, 'BLACK': 13.0,
                          'ASIAN': 6.0, 'OTHER': 4.0}

                existing_keys = {v for v, _, _ in eth_items}
                final_dist = {}
                for val, bp, idx in eth_items:
                    if val in census:
                        current = shares[val]
                        target_val = census[val]
                        final_dist[idx] = round((current + target_val) / 2, 1)
                    else:
                        final_dist[idx] = round(shares.get(val, 0), 1)

                dist_total = sum(final_dist.values())
                if dist_total > 0:
                    final_dist = {k: v / dist_total * 100 for k, v in final_dist.items()}

                for idx, pct in final_dist.items():
                    new_bp = pct * total_bp / 100.0
                    df.at[idx, bp_col] = f'{new_bp:.4f}%'
                    new_raw = round(sample_raw * new_bp / 100.0)
                    df.at[idx, raw_col] = str(new_raw)
                    df.at[idx, proj_col] = str(int(round(new_raw * MULT)))

                all_idx = [idx for _, _, idx in eth_items]
                new_total = sum(
                    float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                    for ix in all_idx
                )
                if new_total > 0:
                    for ix in all_idx:
                        bp_v = float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                        df.at[ix, cs_col] = f"{bp_v / new_total * 100.0:.4f}%"

                print(f"   🔧 Ethnicity fix: {subject_clean} OTHER was {other_pct:.0f}%, WHITE was {white_pct:.0f}%")

            # Additional anti-collapse guard: prevent near-zero major US cohorts.
            # This avoids unrealistic outputs like Hispanic/Latino ~0% for broad US audiences.
            def _pick_idx(_contains):
                for _v, _, _ix in eth_items:
                    _vu = _v.upper()
                    if any(tok in _vu for tok in _contains):
                        return _ix
                return None

            idx_white = _pick_idx(['WHITE'])
            idx_hisp = _pick_idx(['HISPANIC', 'LATINO', 'LATINX'])
            idx_black = _pick_idx(['BLACK', 'AFRICAN AMERICAN'])
            idx_asian = _pick_idx(['ASIAN'])

            shares_by_idx = {idx: (bp / total_bp * 100.0) for _, bp, idx in eth_items}
            mainstream = any(k in bc_upper for k in ['MUSICIAN', 'BAND', 'SOCIAL MEDIA', 'APP', 'PLATFORM', 'MEDIA', 'BROADCAST', 'CABLE', 'SEARCH'])
            floor_hisp = 6.0 if mainstream else 3.0
            floor_black = 4.0 if mainstream else 2.5
            floor_asian = 2.0 if mainstream else 1.0

            needed = 0.0
            if idx_hisp is not None and shares_by_idx.get(idx_hisp, 0.0) < floor_hisp:
                needed += (floor_hisp - shares_by_idx.get(idx_hisp, 0.0))
            if idx_black is not None and shares_by_idx.get(idx_black, 0.0) < floor_black:
                needed += (floor_black - shares_by_idx.get(idx_black, 0.0))
            if idx_asian is not None and shares_by_idx.get(idx_asian, 0.0) < floor_asian:
                needed += (floor_asian - shares_by_idx.get(idx_asian, 0.0))

            if needed > 0.0:
                donor_idx = idx_white
                if donor_idx is None:
                    donor_idx = max(shares_by_idx, key=lambda x: shares_by_idx.get(x, 0.0))
                donor_share = shares_by_idx.get(donor_idx, 0.0)
                take = min(needed, max(0.0, donor_share - 25.0))
                if take > 0:
                    if idx_hisp is not None and shares_by_idx.get(idx_hisp, 0.0) < floor_hisp:
                        delta = min(take, floor_hisp - shares_by_idx[idx_hisp])
                        shares_by_idx[idx_hisp] += delta
                        shares_by_idx[donor_idx] -= delta
                        take -= delta
                    if idx_black is not None and shares_by_idx.get(idx_black, 0.0) < floor_black and take > 0:
                        delta = min(take, floor_black - shares_by_idx[idx_black])
                        shares_by_idx[idx_black] += delta
                        shares_by_idx[donor_idx] -= delta
                        take -= delta
                    if idx_asian is not None and shares_by_idx.get(idx_asian, 0.0) < floor_asian and take > 0:
                        delta = min(take, floor_asian - shares_by_idx[idx_asian])
                        shares_by_idx[idx_asian] += delta
                        shares_by_idx[donor_idx] -= delta
                        take -= delta

                    _write_demo_distribution('ETHNICITY', shares_by_idx)
                    print(f"   🔧 Ethnicity anti-collapse: raised core cohort floors for {subject_clean}")

    # ── INCOME anti-collapse guard ──
    inc_mask = df['Column'].str.upper().str.strip() == 'INCOME'
    if inc_mask.any():
        inc_items = []
        for idx, row in df[inc_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            inc_items.append((val, bp, idx))
        inc_total = sum(bp for _, bp, _ in inc_items)
        if inc_total > 0:
            inc_shares = {idx: (bp / inc_total * 100.0) for _, bp, idx in inc_items}
            max_share = max(inc_shares.values()) if inc_shares else 0.0
            tiny_bins = sum(1 for v in inc_shares.values() if v < 1.0)
            if max_share > 60.0 or tiny_bins >= 3:
                benchmark_by_value = {
                    '$25,000 - $49,999': 22.0,
                    '$50,000 - $74,999': 22.0,
                    '$75,000 - $99,999': 18.0,
                    '$100,000 - $149,999': 17.0,
                    '$150,000 - $249,999': 13.0,
                    '$250,000 OR MORE': 8.0,
                }
                blended = {}
                for val, _, idx in inc_items:
                    canon = val.upper().replace(' ', '')
                    target = None
                    for k, v in benchmark_by_value.items():
                        if canon == k.upper().replace(' ', ''):
                            target = v
                            break
                    if target is None:
                        target = 100.0 / max(len(inc_items), 1)
                    cur = inc_shares.get(idx, 0.0)
                    blended[idx] = 0.55 * cur + 0.45 * target

                _write_demo_distribution('INCOME', blended)
                print(f"   🔧 Income anti-collapse: rebalanced implausible tails for {subject_clean}")

    # ── Cap "Prefer Not to Say" at 5% across all demographic categories ──
    PNS_CAP = 5.0
    for cat in ['AGE', 'GENDER', 'ETHNICITY', 'EDUCATION', 'INCOME',
                'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'RELATIONSHIP']:
        cat_mask = df['Column'].str.upper().str.strip() == cat
        if not cat_mask.any():
            continue
        cat_items = []
        for idx, row in df[cat_mask].iterrows():
            val = str(row.get('Value', '')).strip().upper()
            try:
                bp = float(str(row.get(bp_col, 0)).replace('%', '').replace(',', ''))
            except (ValueError, TypeError):
                bp = 0.0
            cat_items.append((val, bp, idx))
        total_bp = sum(bp for _, bp, _ in cat_items)
        if total_bp <= 0:
            continue
        shares = {v: bp / total_bp * 100 for v, bp, _ in cat_items}
        pns_pct = shares.get('PREFER NOT TO SAY', 0)
        if pns_pct <= PNS_CAP:
            continue
        excess = pns_pct - PNS_CAP
        non_pns = {v: s for v, s in shares.items() if v != 'PREFER NOT TO SAY'}
        non_pns_total = sum(non_pns.values())
        if non_pns_total <= 0:
            continue
        sample_raw = 0
        ss_mask = df['Column'].str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_raw = max(1, int(float(
                    str(df.loc[ss_mask, raw_col].iloc[0]).replace(',', '')
                )))
            except (ValueError, TypeError):
                sample_raw = 1
        new_dist = {}
        for val, bp, idx in cat_items:
            if val == 'PREFER NOT TO SAY':
                new_dist[idx] = PNS_CAP
            else:
                new_dist[idx] = shares[val] + excess * (shares[val] / non_pns_total)
        d_total = sum(new_dist.values())
        if d_total > 0:
            new_dist = {k: v / d_total * 100 for k, v in new_dist.items()}
        for idx, pct in new_dist.items():
            new_bp = pct * total_bp / 100.0
            df.at[idx, bp_col] = f'{new_bp:.4f}%'
            new_raw = round(sample_raw * new_bp / 100.0)
            df.at[idx, raw_col] = str(new_raw)
            df.at[idx, proj_col] = str(int(round(new_raw * MULT)))
        all_idx = [idx for _, _, idx in cat_items]
        new_total = sum(
            float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
            for ix in all_idx
        )
        if new_total > 0:
            for ix in all_idx:
                bp_v = float(str(df.at[ix, bp_col]).replace('%', '').replace(',', ''))
                df.at[ix, cs_col] = f"{bp_v / new_total * 100.0:.4f}%"
        print(f"   🔧 'Prefer Not to Say' cap: {cat} was {pns_pct:.1f}% → {PNS_CAP}%")

    return df


