def enforce_distribution_realism(df, brand_category=None, project_name=None, brands=None):
    """
    Final-pass auto-audit that detects and fixes STRUCTURAL distribution problems
    without hard-capping any individual item. Context-aware: uses the profile's own
    identity (project_name, brand_category) to avoid penalising items that SHOULD
    be high for that persona.

    What it fixes:
    1. Flat top-N clusters — items suspiciously close in BP (always wrong)
    2. Flat mid-tier walls — large blocks of items at near-identical BP

    What it does NOT do:
    - Hard-cap any item to an absolute number (Zoom SHOULD be high for a Zoom profile)
    - Force specific leaders (the scoring agents + calibration blocks handle that)
    """
    import pandas as pd
    import random as _rnd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    out = df.copy()
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    if not bp_col:
        return out
    cs_col = 'Category Share' if 'Category Share' in out.columns else 'Percentage'
    pct_col = 'Percentage' if 'Percentage' in out.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None
    MULT = 329_900_000 / 10_000_000

    sample_size = 132040
    if raw_col:
        ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(out.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass

    SKIP_CATS = {'AGE', 'GENDER', 'ETHNICITY', 'INCOME', 'EDUCATION', 'RELATIONSHIP',
                 'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'OCCUPATION', 'LOCATION',
                 'SAMPLE SIZE', 'BRAND INPUT', 'BRAND CATEGORY', 'FOOTWEAR',
                 'AVID FAN', 'CASUAL FAN', 'TOTAL FAN'}

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    def _write_bp(idx, new_bp):
        new_bp = max(0.01, min(float(new_bp), 99.0))
        s = f"{new_bp:.4f}"
        out.at[idx, bp_col] = s
        if cs_col in out.columns:
            out.at[idx, cs_col] = s
        if pct_col in out.columns:
            out.at[idx, pct_col] = s
        if raw_col:
            raw = max(1, int(round(new_bp / 100.0 * sample_size)))
            out.at[idx, raw_col] = str(raw)
            if proj_col:
                out.at[idx, proj_col] = str(int(round(raw * MULT)))

    def _cat_rows(cat):
        m = out['Column'].astype(str).str.upper().str.strip() == str(cat).upper()
        rows = []
        for idx, row in out[m].iterrows():
            rows.append((idx, str(row.get('Value', '')).strip(), _to_num(row.get(bp_col, 0))))
        rows.sort(key=lambda x: -x[2])
        return rows

    fixes = 0
    audit_log = []

    # ─── 1) ANTI-FLAT TOP-N: break up suspiciously flat top clusters ─────
    # A "wall" of 5+ items within <4% of each other (all above 8% BP)
    # is never realistic — real distributions have clear tiers with gaps.
    all_cats = out['Column'].astype(str).str.upper().str.strip().unique()
    for cat in all_cats:
        if cat in SKIP_CATS:
            continue
        rows = _cat_rows(cat)
        if len(rows) < 5:
            continue

        top5_bps = [r[2] for r in rows[:5]]
        spread = top5_bps[0] - top5_bps[4]

        if spread < 4.0 and top5_bps[0] > 8.0:
            base_top = top5_bps[0]
            decay_targets = [
                base_top,
                base_top * _rnd.uniform(0.82, 0.90),
                base_top * _rnd.uniform(0.70, 0.80),
                base_top * _rnd.uniform(0.60, 0.72),
                base_top * _rnd.uniform(0.50, 0.64),
            ]
            for i in range(1, min(5, len(rows))):
                idx, val, cur_bp = rows[i]
                target = decay_targets[i]
                if target < cur_bp:
                    _write_bp(idx, target)
                    fixes += 1

            # Also spread items 6-10 if they're bunched against items 1-5
            if len(rows) >= 10:
                tier2_base = decay_targets[4] * _rnd.uniform(0.75, 0.88)
                for i in range(5, min(10, len(rows))):
                    idx, val, cur_bp = rows[i]
                    target = tier2_base * (1.0 - (i - 5) * _rnd.uniform(0.04, 0.08))
                    if cur_bp > target + 2.0:
                        _write_bp(idx, target)
                        fixes += 1

            audit_log.append(f"FLAT-FIX {cat}: top-5 spread was {spread:.1f}%, redistributed")

    # ─── 2) ANTI-FLAT MID-TIER WALLS ─────────────────────────────────────
    # Detect blocks of 8+ consecutive items within <1.5% of each other
    # in the middle of a category and spread them with natural decay.
    for cat in all_cats:
        if cat in SKIP_CATS:
            continue
        rows = _cat_rows(cat)
        if len(rows) < 12:
            continue

        i = 3  # start checking after top 3
        while i < len(rows) - 4:
            block_start = i
            while i < len(rows) - 1 and abs(rows[i][2] - rows[i + 1][2]) < 1.5 and rows[i][2] > 1.0:
                i += 1
            block_len = i - block_start + 1
            if block_len >= 8:
                anchor_bp = rows[block_start][2]
                for j in range(block_start, i + 1):
                    step = j - block_start
                    decay = anchor_bp * (1.0 - step * _rnd.uniform(0.02, 0.05))
                    decay = max(decay, 0.01)
                    if abs(rows[j][2] - decay) > 0.5:
                        _write_bp(rows[j][0], decay)
                        fixes += 1
                audit_log.append(
                    f"WALL-FIX {cat}: {block_len} items bunched at ~{anchor_bp:.1f}%, spread with decay"
                )
            i += 1

    # ─── 3) PRINT AUDIT SUMMARY ──────────────────────────────────────────
    if not SILENCE_VERBOSE_OUTPUT and audit_log:
        print(f"\n🔍 Distribution realism audit: {fixes} fix(es)")
        for entry in audit_log:
            print(f"   • {entry}")

    return out


def enforce_behavioral_bp_uniqueness(df):
    """
    Reduce synthetic-looking repeated Brand Penetration values in behavioral
    categories by applying tiny deterministic jitter to ties.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    out = df.copy()
    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in out.columns else None
    if not bp_col:
        return out
    cs_col = 'Category Share' if 'Category Share' in out.columns else 'Percentage'
    pct_col = 'Percentage' if 'Percentage' in out.columns else cs_col
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in out.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in out.columns else None
    MULT = 329_900_000 / 10_000_000

    demo_meta = {
        'AGE', 'GENDER', 'ETHNICITY', 'INCOME', 'EDUCATION', 'RELATIONSHIP',
        'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'OCCUPATION', 'LOCATION',
        'INPUT_METADATA', 'BRAND INPUT', 'SAMPLE SIZE', 'AVID FAN', 'CASUAL FAN', 'BRAND CATEGORY'
    }

    def _to_num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    sample_size = 132040
    if raw_col:
        ss_mask = out['Column'].astype(str).str.upper().str.strip() == 'SAMPLE SIZE'
        if ss_mask.any():
            try:
                sample_size = max(1, int(float(str(out.loc[ss_mask, raw_col].iloc[0]).replace(',', ''))))
            except Exception:
                pass

    touched = 0
    for cat in out['Column'].astype(str).str.upper().str.strip().unique():
        if cat in demo_meta:
            continue
        cm = out['Column'].astype(str).str.upper().str.strip() == cat
        sub = out[cm].copy()
        if sub.empty:
            continue
        sub['_bp'] = sub[bp_col].map(_to_num).round(4)
        dup_counts = sub['_bp'].value_counts()
        dup_vals = [v for v, c in dup_counts.items() if c > 1 and v >= 0.05]
        if not dup_vals:
            continue
        for dv in dup_vals:
            dup_idx = list(sub[sub['_bp'] == dv].index)
            for k, ridx in enumerate(dup_idx):
                # deterministic micro-jitter (~0.0001-0.0490) with alternating sign.
                # Wider spread avoids repeated 4-decimal ties across large groups.
                step = ((abs(hash(f"{cat}|{ridx}|{k}")) % 490) + 1) / 10000.0
                sign = -1.0 if (k % 2 == 0) else 1.0
                new_bp = max(0.01, min(95.0, dv + sign * step))
                s = f"{new_bp:.4f}"
                out.at[ridx, bp_col] = s
                if cs_col in out.columns:
                    out.at[ridx, cs_col] = s
                if pct_col in out.columns:
                    out.at[ridx, pct_col] = s
                if raw_col:
                    raw = max(1, int(round(new_bp / 100.0 * sample_size)))
                    out.at[ridx, raw_col] = str(raw)
                    if proj_col:
                        out.at[ridx, proj_col] = str(int(round(raw * MULT)))
                touched += 1

        # Second pass: de-round suspiciously "perfect" values like 40.0004,
        # 25.0006, 60.0098 in behavioral categories.
        for ridx in sub.index:
            cur = _to_num(out.at[ridx, bp_col])
            if cur <= 0.01:
                continue
            frac = abs(cur - round(cur))
            near_integer = (frac < 0.02) or (frac > 0.98)
            # Also catch values that are effectively one-decimal/whole-number shapes.
            near_one_decimal = abs(cur - round(cur, 1)) < 0.01
            if not (near_integer or near_one_decimal):
                continue
            # Deterministic perturbation: 0.0830..0.3470
            mag = ((abs(hash(f"deround|{cat}|{ridx}")) % 265) + 83) / 1000.0
            sign = -1.0 if (abs(hash(f"sign|{cat}|{ridx}")) % 2 == 0) else 1.0
            new_bp = max(0.01, min(95.0, cur + sign * mag))
            # If this still lands near integer, nudge again.
            nfrac = abs(new_bp - round(new_bp))
            if nfrac < 0.01 or nfrac > 0.99:
                new_bp = max(0.01, min(95.0, new_bp + (0.137 if sign < 0 else -0.137)))
            s = f"{new_bp:.4f}"
            out.at[ridx, bp_col] = s
            if cs_col in out.columns:
                out.at[ridx, cs_col] = s
            if pct_col in out.columns:
                out.at[ridx, pct_col] = s
            if raw_col:
                raw = max(1, int(round(new_bp / 100.0 * sample_size)))
                out.at[ridx, raw_col] = str(raw)
                if proj_col:
                    out.at[ridx, proj_col] = str(int(round(raw * MULT)))
            touched += 1

    if not SILENCE_VERBOSE_OUTPUT and touched:
        print(f"🎛️ Behavioral BP uniqueness guard: jittered {touched} tied values")
    return out

def deduplicate_values_within_category(df):
    """
    Final safeguard: remove duplicate Value rows inside each Column category.
    Keeps one row per canonicalized value and sums percentages/counts.
    """
    import pandas as pd

    if 'Column' not in df.columns or 'Value' not in df.columns:
        return df

    bp_col = 'Brand Penetration (Row)' if 'Brand Penetration (Row)' in df.columns else None
    cs_col = 'Category Share' if 'Category Share' in df.columns else None
    pct_col = 'Percentage' if 'Percentage' in df.columns else None
    raw_col = 'Original Raw Numbers' if 'Original Raw Numbers' in df.columns else None
    proj_col = 'US Gen Pop Projection' if 'US Gen Pop Projection' in df.columns else None

    def _num(v):
        try:
            return float(str(v).replace(',', '').replace('%', ''))
        except Exception:
            return 0.0

    out = df.copy()
    out['_ROW_POS'] = range(len(out))
    out['_CAT_KEY'] = out['Column'].astype(str).str.strip().str.upper()
    out['_VAL_KEY'] = out.apply(
        lambda r: _canonical_demo_value(str(r['Column']), str(r['Value'])),
        axis=1
    )

    keep_rows = []
    for (cat_key, val_key), g in out.groupby(['_CAT_KEY', '_VAL_KEY'], dropna=False, sort=False):
        row = g.iloc[0].copy()
        row['Column'] = cat_key
        row['Value'] = str(g.iloc[0]['Value']).strip()
        row['_ROW_POS'] = int(g['_ROW_POS'].min())
        # Sum numeric-like metrics where present
        if bp_col:
            row[bp_col] = sum(_num(v) for v in g[bp_col].tolist())
        if cs_col:
            row[cs_col] = sum(_num(v) for v in g[cs_col].tolist())
        if pct_col and (cs_col is None or pct_col != cs_col):
            row[pct_col] = sum(_num(v) for v in g[pct_col].tolist())
        if raw_col:
            row[raw_col] = int(round(sum(_num(v) for v in g[raw_col].tolist())))
        if proj_col:
            row[proj_col] = int(round(sum(_num(v) for v in g[proj_col].tolist())))
        keep_rows.append(row)

    result = pd.DataFrame(keep_rows)
    if '_ROW_POS' in result.columns:
        result = result.sort_values(by=['_ROW_POS'], kind='stable')
    result = result.drop(columns=['_CAT_KEY', '_VAL_KEY', '_ROW_POS'], errors='ignore')
    if not SILENCE_VERBOSE_OUTPUT:
        removed = len(df) - len(result)
        if removed > 0:
            print(f"🧹 Final category dedupe: removed {removed} duplicate rows")
    return result

def ensure_all_dmas_present(df):
    """
    Ensure all major US DMAs are present in the LOCATION category.
    Add missing DMAs with small random percentages.
    """
    
    if not SILENCE_VERBOSE_OUTPUT:
        print("\n📍 ENSURING ALL DMAS ARE PRESENT")
        print("=" * 40)
    
    # Use the comprehensive ALLOWED_DMAS list (210 DMAs)
    major_dmas = list(ALLOWED_DMAS)
    
    # First, filter out invalid DMAs (short versions like "Augusta GA" that aren't in ALLOWED_DMAS)
    df = filter_invalid_dmas(df)
    
    # Then deduplicate any remaining LOCATION entries
    df = deduplicate_location_data(df)
    
    # Normalize existing LOCATION display names
    location_mask = df['Column'].str.upper() == 'LOCATION'
    if location_mask.any():
        df.loc[location_mask, 'Value'] = df.loc[location_mask, 'Value'].apply(normalize_dma_for_display)
    
    # Find existing LOCATION entries (use match keys for case-insensitive comparison)
    existing_locations = set()
    existing_keys = set()
    
    if location_mask.any():
        existing_locations = set(df[location_mask]['Value'])
        existing_keys = set(df[location_mask]['Value'].apply(dma_match_key))
        if not SILENCE_VERBOSE_OUTPUT:
            print(f"  📊 Found {len(existing_locations)} existing locations (after deduplication)")
    
    missing_dmas = []
    for dma in major_dmas:
        dma_key = dma_match_key(dma)
        if dma_key in existing_keys:
            continue
        if any(dma_key in ek or ek in dma_key for ek in existing_keys):
            continue
        missing_dmas.append(dma)
    
    if missing_dmas:
        if not SILENCE_VERBOSE_OUTPUT:
            print(f"  📍 Adding {len(missing_dmas)} missing DMAs")
        
        # Calculate total existing percentage for LOCATION
        if location_mask.any():
            existing_total = pd.to_numeric(df[location_mask]['Percentage'], errors='coerce').sum()
            existing_dmas = df[location_mask].copy()
        else:
            existing_total = 0
            existing_dmas = pd.DataFrame()
            
        # Strategy: Add all missing DMAs with very small percentages
        # Then let the demographic normalization handle scaling everything to 100%
        
        # Give each missing DMA a very small percentage (0.01% to 0.05%)
        # This ensures they survive the normalization process
        new_rows = []
        for i, dma in enumerate(missing_dmas):
            # Very small but visible percentage for each DMA
            small_percentage = np.random.uniform(0.01, 0.05)
            
            new_row = {
                'Column': 'LOCATION',
                'Value': normalize_dma_for_display(dma),
                'Percentage': round(small_percentage, 4)
            }
            new_rows.append(new_row)
        
        # Add new rows to dataframe
        if new_rows:
            new_df = pd.DataFrame(new_rows)
            df = pd.concat([df, new_df], ignore_index=True)
            print(f"    ✅ Added {len(new_rows)} DMAs with small percentages (0.01-0.05%)")
            
            # Show total DMA count
            total_location_count = len(df[df['Column'].str.upper() == 'LOCATION'])
            print(f"    📊 Total LOCATION entries: {total_location_count}")
            
            # Calculate new total - will be over 100% but normalization will fix it
            new_total = pd.to_numeric(df[df['Column'].str.upper() == 'LOCATION']['Percentage'], errors='coerce').sum()
            print(f"    📈 Total LOCATION percentage: {new_total:.2f}% (will be normalized to 100%)")
    else:
        print("  ✅ All major DMAs already present")
    
    return df

def normalize_demographic_categories(df):
    """
    Ensure all demographic categories total to exactly 100%.
    First recalculates percentages from Original Raw Numbers, then normalizes.
    """
    
    
    if not SILENCE_VERBOSE_OUTPUT:
        print("\n📊 NORMALIZING DEMOGRAPHIC CATEGORIES TO 100%")
        print("=" * 50)
    
    # First, recalculate percentages from Original Raw Numbers to ensure alignment
    df = recalculate_percentages_from_raw_numbers(df)
    
    # Count DMAs before normalization
    location_count_before = len(df[df['Column'].str.upper() == 'LOCATION'])
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"  📍 LOCATION entries before normalization: {location_count_before}")
    
    # Define demographic categories that should total to 100%
    demographic_categories = [
        'GENDER', 'AGE', 'ETHNICITY', 'INCOME', 'EDUCATION', 
        'RELATIONSHIP', 'SEXUAL_ORIENTATION', 'PARENTAL_STATUS', 'LOCATION'
    ]
    
    for category in demographic_categories:
        # Find category (case insensitive and exact match to avoid EDUCATION & LEARNING)
        if category.upper() == 'EDUCATION':
            # Only match exact "EDUCATION", not "EDUCATION & LEARNING"
            cat_mask = df['Column'].str.upper() == 'EDUCATION'
        else:
            cat_mask = df['Column'].str.upper() == category.upper()
        
        if not cat_mask.any():
            continue
            
        # Get current values
        cat_indices = df[cat_mask].index
        df.loc[cat_indices, 'Percentage'] = pd.to_numeric(df.loc[cat_indices, 'Percentage'], errors='coerce')
        
        current_total = df.loc[cat_indices, 'Percentage'].sum()
        
        if abs(current_total - 100.0) > 0.01:  # Only normalize if not already close to 100%
            if not SILENCE_VERBOSE_OUTPUT:
                print(f"  📊 {category}: {current_total:.2f}% → 100.00%")
            
            # Proportionally scale all values to total 100%
            scale_factor = 100.0 / current_total
            df.loc[cat_indices, 'Percentage'] = df.loc[cat_indices, 'Percentage'] * scale_factor
            
            # Ensure 4 decimal precision
            df.loc[cat_indices, 'Percentage'] = df.loc[cat_indices, 'Percentage'].round(4)
            
            # Handle any tiny rounding errors by adjusting the largest value
            new_total = df.loc[cat_indices, 'Percentage'].sum()
            if abs(new_total - 100.0) > 0.0001:
                # Find largest value and adjust it to make total exactly 100%
                largest_idx = df.loc[cat_indices, 'Percentage'].idxmax()
                adjustment = 100.0 - new_total
                df.at[largest_idx, 'Percentage'] = df.at[largest_idx, 'Percentage'] + adjustment
                df.at[largest_idx, 'Percentage'] = round(df.at[largest_idx, 'Percentage'], 4)
            
            # Verify final total
            final_total = df.loc[cat_indices, 'Percentage'].sum()
            if not SILENCE_VERBOSE_OUTPUT:
                print(f"    ✅ Final total: {final_total:.4f}%")
        else:
            if not SILENCE_VERBOSE_OUTPUT:
                print(f"  ✅ {category}: {current_total:.2f}% (already normalized)")
    
    # Count DMAs after normalization
    location_count_after = len(df[df['Column'].str.upper() == 'LOCATION'])
    if not SILENCE_VERBOSE_OUTPUT:
        print(f"  📍 LOCATION entries after normalization: {location_count_after}")
    
    return df

